 <path d="M9 15.5A6.5 6.5 0 1 0 9 2.5a6.5 6.5 0 0 0 0 13ZM14 14l3.5 3.5" stroke="currentColor"
 stroke-width="1.7" stroke-linecap="round" />
 </svg>
 <input id="dt-or-item-search" type="search" class="dt-item-control dt-item-search"
 placeholder="Search item / product / supplier..." x-model="searchValue"
 x-on:input="startLoading('Mencari item...')" x-on:input.debounce.500ms="updateSearch()"
 x-on:keydown.enter.prevent.stop="void 0" data-dt-or-search>
 </div>

 <button type="button" class="dt-item-nav-button" data-dt-or-filter-toggle
 x-on:click="filterOpen = ! filterOpen">
