 x-bind:disabled="isLoading || isAddingItem || !@js($row['is_dirty'])"
 x-on:click="applyInlineItem(@js($row['key']))">
 Simpan Perubahan Item
 </button>
 <button type="button" class="dt-item-delete-text"
