 <li>{{ $errorMessage }}</li>
 @endforeach
 </ul>
 </div>
 @endif
 <div class="dt-item-inline-editor" data-dt-inline-editor="{{ $row['key'] }}">
 <div class="dt-item-inline-grid">
 @if ($row['is_status_locked'])
 <div class="dt-item-lock-banner">Item {{ $row['status_label'] }} tidak
 bisa diedit dari inline editor. Gunakan bulk action untuk mengembalikan
 ke Draft jika perlu revisi.</div>
 @endif
 <div class="dt-item-inline-field wide">
