 public static function resolveApprovalGateStatus(?string $status): ?string
 {
 $normalized = OrderRequestItem::normalizeApprovalStatus($status);

 return in_array($normalized, [
 OrderRequestItem::STATUS_APPROVED,
 OrderRequestItem::STATUS_REJECTED,
 ], true) ? $normalized : OrderRequestItem::STATUS_APPROVED;
 }

 public static function validateApprovalGateItemDecisions(array $data): void
 {
 $selectedItems = collect($data['selected_items'] ?? []);
 $validDecisions = [
 OrderRequestItem::STATUS_APPROVED,
 OrderRequestItem::STATUS_REJECTED,
 ];

 if ($selectedItems->isEmpty()) {
 throw ValidationException::withMessages([
 'selected_items' => 'Pilih keputusan untuk semua item sebelum menyetujui Order Request.',
 ]);
 }

 $hasMissingDecision = $selectedItems->contains(
 fn (array $row): bool => ! in_array($row['approval_status'] ?? null, $validDecisions, true)
 );

 if ($hasMissingDecision) {
 throw ValidationException::withMessages([
 'selected_items' => 'Pilih keputusan untuk semua item sebelum menyetujui Order Request.',
 ]);
 }

 $hasRejectedWithoutNote = $selectedItems->contains(
 fn (array $row): bool => ($row['approval_status'] ?? null) === OrderRequestItem::STATUS_REJECTED
 && trim((string) ($row['rejection_note'] ?? '')) === ''
 );

 if ($hasRejectedWithoutNote) {
 throw ValidationException::withMessages([
 'selected_items' => 'Alasan reject wajib diisi untuk item yang ditolak.',
 ]);
 }

 if (! empty($data['create_purchase_order'])) {
 $approvedIncludedItems = self::selectedPurchaseOrderApprovedItems($selectedItems);
 $itemsWithoutSupplier = $approvedIncludedItems->filter(
 fn (array $row): bool => empty($row['item_supplier_id'])
 );

 if ($itemsWithoutSupplier->isNotEmpty()) {
 $productNames = $itemsWithoutSupplier
 ->pluck('product_name')
 ->filter()
 ->take(3)
 ->implode(', ');

 $suffix = $itemsWithoutSupplier->count() > 3 ? ', dan item lainnya' : '';
 $msg = "Item ({$productNames}{$suffix}) belum memiliki supplier. Tentukan supplier terlebih dahulu atau matikan opsi Buat Purchase Order otomatis.";

 throw ValidationException::withMessages([
 'create_purchase_order' => $msg,
 'selected_items' => $msg,
 ]);
 }
 }
 }

 public static function hasApprovedItemsAvailableForPurchaseOrder(OrderRequest $record): bool
 {
 $record->loadMissing('orderRequestItem');

 return $record->orderRequestItem->contains(function (OrderRequestItem $item): bool {
 if (OrderRequestItem::normalizeApprovalStatus($item->status ?? null) !== OrderRequestItem::STATUS_APPROVED) {
 return false;
 }

 return OrderRequestQuantityLock::orderRequestItemLimit((int) $item->id)['remaining_for_po'] > 0;
 });
 }

 public static function selectedPurchaseOrderItemApprovalStatus(array $item): string
 {
 if (array_key_exists('approval_status', $item)) {
 return OrderRequestItem::normalizeApprovalStatus($item['approval_status'] ?? null);
 }

 return OrderRequestItem::STATUS_DRAFT;
 }

 public static function selectedPurchaseOrderApprovedItems(iterable $items): \Illuminate\Support\Collection
 {
 return collect($items)
 ->filter(fn ($item) => ! empty($item['include']))
 ->filter(fn ($item) => self::selectedPurchaseOrderItemApprovalStatus((array) $item) === OrderRequestItem::STATUS_APPROVED);
 }

 public static function approvalOutcomeNotification(OrderRequest $record): array
 {
 $record->loadMissing('orderRequestItem');

 $statuses = $record->orderRequestItem
 ->map(fn (OrderRequestItem $item) => OrderRequestItem::normalizeApprovalStatus($item->status ?? null));

 $approvedCount = $statuses->filter(fn (string $status) => $status === OrderRequestItem::STATUS_APPROVED)->count();
 $rejectedCount = $statuses->filter(fn (string $status) => $status === OrderRequestItem::STATUS_REJECTED)->count();

 if ($statuses->isNotEmpty() && $rejectedCount === $statuses->count()) {
 return [
 'isSuccess' => true,
 'title' => 'Information',
 'message' => 'Order Request ditolak karena semua item ditolak.',
 ];
 }

 if ($approvedCount === 0) {
 return [
 'isSuccess' => false,
 'title' => 'Perhatian',
 'message' => 'Order Request tidak dapat di-approve karena tidak ada item yang disetujui. Approve minimal satu item atau reject Order Request.',
 ];
 }

 if ($record->status === 'partial' || $rejectedCount > 0 || $approvedCount < $statuses->count()) {
 return [
 'isSuccess' => true,
 'title' => 'Information',
 'message' => 'Order Request disetujui sebagian. Hanya item Approved yang dapat dibuatkan Purchase Order.',
 ];
 }

 return [
 'isSuccess' => true,
 'title' => 'Information',
 'message' => 'Order Request telah disetujui.',
 ];
 }

 public static function resolveProductSupplierId(?int $productId): ?int
 {
 if (! $productId) {
 return null;
 }

 $product = Product::withoutGlobalScope('product_cabang')->with('suppliers')->find($productId);

 if (! $product) {
 return null;
 }

 $recommended = $product->suppliers
 ->filter(fn (Supplier $supplier) => $supplier->pivot?->supplier_price !== null)
 ->sortBy(fn (Supplier $supplier) => sprintf(
 '%020.6f|%s',
 (float) $supplier->pivot->supplier_price,
 Str::lower((string) $supplier->perusahaan)
 ))
 ->first();

 if ($recommended?->id) {
 return (int) $recommended->id;
 }

 if ($product->supplier_id) {
 return (int) $product->supplier_id;
 }

 return $product->suppliers
 ->sortBy(fn (Supplier $supplier) => Str::lower((string) $supplier->perusahaan))
 ->first()?->id;
 }

 public static function resolveSupplierOptions(?int $productId = null, ?string $search = null, int $limit = 50, ?int $currencyId = null): array
 {
 $query = Supplier::query();

 $product = null;
 $linkedSupplierIds = [];
 $linkedPriceMap = [];

 if ($productId) {
 $product = Product::withoutGlobalScope('product_cabang')->find($productId);

 $linkedRows = DB::table('product_supplier')
 ->where('product_id', $productId)
 ->get(['supplier_id', 'supplier_price']);

 foreach ($linkedRows as $row) {
 $supplierId = (int) $row->supplier_id;
 $linkedSupplierIds[] = $supplierId;
 $linkedPriceMap[$supplierId] = $row->supplier_price !== null
 ? (float) $row->supplier_price
 : null;
 }

 if ($product?->supplier_id) {
 $linkedSupplierIds[] = (int) $product->supplier_id;
 }

 $linkedSupplierIds = array_values(array_unique(array_map('intval', $linkedSupplierIds)));
 }

 if ($search !== null && $search !== '') {
 $query->where(function ($supplierQuery) use ($search) {
 $supplierQuery->where('perusahaan', 'like', "%{$search}%")
 ->orWhere('code', 'like', "%{$search}%");
 });
 }

 $linkedSuppliers = empty($linkedSupplierIds)
 ? collect()
 : (clone $query)
 ->whereIn('id', $linkedSupplierIds)
 ->get()
 ->sortBy(function (Supplier $supplier) use ($linkedPriceMap) {
 $supplierId = (int) $supplier->id;
 $price = $linkedPriceMap[$supplierId] ?? null;

 return sprintf(
 '%d|%020.6f|%s',
 $price !== null ? 0 : 1,
 $price ?? PHP_FLOAT_MAX,
 Str::lower((string) $supplier->perusahaan)
 );
 });
 $remainingLimit = max(0, $limit - $linkedSuppliers->count());
 $remainingSuppliers = $remainingLimit === 0
 ? collect()
 : (clone $query)
 ->when(! empty($linkedSupplierIds), fn (Builder $supplierQuery) => $supplierQuery->whereNotIn('id', $linkedSupplierIds))
 ->orderBy('perusahaan')
 ->limit($remainingLimit)
 ->get();
 $suppliers = $linkedSuppliers
 ->concat($remainingSuppliers)
 ->take($limit);

 return $suppliers
 ->mapWithKeys(function ($supplier) use ($productId, $linkedPriceMap, $currencyId) {
 $priceLabel = '';
 if ($productId) {
 $price = $linkedPriceMap[(int) $supplier->id] ?? null;
 if ($price !== null) {
 $converted = self::convertIdrToCurrency((float) $price, $currencyId, false);
 $priceLabel = ' - ' . self::formatMoneyByCurrency($currencyId, $converted);
 }
 }

 return [$supplier->id => "({$supplier->code}) {$supplier->perusahaan} {$priceLabel}"];
 })
 ->all();
 }

 public static function resolveSupplierLabel(?int $supplierId, ?int $productId = null, ?int $currencyId = null): ?string
 {
 if (! $supplierId) {
 return null;
 }

 $supplier = Supplier::find($supplierId);

 $priceLabel = '';
 if ($productId && $supplier) {
 $product = Product::withoutGlobalScope('product_cabang')->find($productId);
 $price = $product?->suppliers()->where('suppliers.id', $supplierId)->first()?->pivot?->supplier_price;
 if ($price !== null) {
 $converted = self::convertIdrToCurrency((float) $price, $currencyId, false);
 $priceLabel = ' - ' . self::formatMoneyByCurrency($currencyId, $converted);
 }
 }

 return $supplier ? trim("({$supplier->code}) {$supplier->perusahaan} {$priceLabel}") : null;
 }

