 ->dehydrated(true),
 Hidden::make('tax_type')
 ->reactive()
 ->afterStateUpdated(function ($state, callable $set, callable $get) {
 $normalized = self::normalizeTaxTypeValue($state ?? null);
 $items = $get('orderRequestItem') ?? [];
 foreach (array_keys($items) as $idx) {
